    58	// Match parses a literal, glob, regexp, or matcher function expression.
    59	func Match(value string) (Matcher, error) {
    60		match := reVariable.FindStringSubmatch(value)
    61		if len(match) == 0 {
    62			if strings.Contains(value, "{{") || strings.Contains(value, "}}") {
    63				return nil, trace.BadParameter("%q is using template brackets '{{' or '}}', however expression does not parse, make sure the format is {{expression}}", value)
    64			}
    65			return compileGlob(value)
    66		}
    67		prefix, expression, suffix := match[1], match[2], match[3]
    68		expr, err := parser.ParseExpr(expression)
    69		if err != nil {
    70			return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", value)
    71		}
    72		root, ok := expr.(*ast.CallExpr)
    73		if !ok {
    74			if _, variable := expr.(*ast.Ident); variable {
    75				return nil, trace.BadParameter("%q is not a valid matcher expression - no variables and transformations are allowed", value)
    76			}
    77			return compileGlob(strings.TrimSpace(prefix) + strings.TrimSpace(expression) + strings.TrimSpace(suffix))
    78		}
    79		call, ok := root.Fun.(*ast.SelectorExpr)
    80		if !ok {
    81			return nil, trace.BadParameter("unsupported matcher function %v", root.Fun)
    82		}
    83		ns, ok := call.X.(*ast.Ident)
    84		if !ok {
    85			return nil, trace.BadParameter("unsupported matcher function namespace")
    86		}
    87		if ns.Name != "regexp" && ns.Name != EmailNamespace {
    88			return nil, trace.BadParameter("unsupported function namespace %s, supported namespaces are email and regexp", ns.Name)
    89		}
    90		if ns.Name == EmailNamespace && call.Sel.Name != EmailLocalFnName {
    91			return nil, trace.BadParameter("unsupported function email.%s, supported functions are: email.local", call.Sel.Name)
    92		}
    93		if ns.Name == "regexp" && call.Sel.Name != "match" && call.Sel.Name != "not_match" {
    94			return nil, trace.BadParameter("unsupported function regexp.%s, supported functions are: regexp.match, regexp.not_match", call.Sel.Name)
    95		}
    96		if len(root.Args) != 1 {
    97			return nil, trace.BadParameter("expected 1 argument for %s.%s got %v", ns.Name, call.Sel.Name, len(root.Args))
    98		}
    99		lit, ok := root.Args[0].(*ast.BasicLit)
   100		if !ok || lit.Kind != token.STRING {
   101			return nil, trace.BadParameter("argument for %s.%s must be a string literal", ns.Name, call.Sel.Name)
   102		}
   103		pattern, err := strconv.Unquote(lit.Value)
   104		if err != nil {
   105			return nil, trace.Wrap(err)
   106		}
   107		var inner Matcher
   108		if ns.Name == EmailNamespace {
   109			inner = emailLocalMatcher{}
   110		} else {
   111			inner, err = compileRawRegexp(pattern)
   112			if err != nil {
   113				return nil, err
   114			}
   115			if call.Sel.Name == "not_match" {
   116				inner = notMatcher{matcher: inner}
   117			}
   118		}
   119		if prefix != "" || suffix != "" {
   120			inner = prefixSuffixMatcher{prefix: strings.TrimLeftFunc(prefix, unicode.IsSpace), suffix: strings.TrimRightFunc(suffix, unicode.IsSpace), matcher: inner}
   121		}
   122		return inner, nil
   123	}
