   125	func compileGlob(pattern string) (Matcher, error) {
   126		return compileRawRegexp("^" + utils.GlobToRegexp(pattern) + "$")
   127	}
   128	
   129	func compileRawRegexp(pattern string) (Matcher, error) {
   130		re, err := regexp.Compile(pattern)
   131		if err != nil {
   132			return nil, trace.BadParameter("failed parsing regexp %q: %v", pattern, err)
   133		}
   134		return regexpMatcher{re: re}, nil
   135	}
