   146	type Expression struct {
   147		// namespace is expression namespace,
   148		// e.g. internal.traits has a variable traits
   149		// in internal namespace
   150		namespace string
   151		// variable is a variable name, e.g. trait name,
   152		// e.g. internal.traits has variable name traits
   153		variable string
   154		// prefix is a prefix of the string
