   162	// emailLocalTransformer extracts local part of the email.
   163	type emailLocalTransformer struct{}
   164	
   165	// EmailLocal returns local part of the email
   166	func (emailLocalTransformer) transform(in string) (string, error) {
   167		if in == "" {
   168			return "", trace.BadParameter("address is empty")
   169		}
   170		addr, err := mail.ParseAddress(in)
   171		if err != nil {
   172			return "", trace.BadParameter("failed to parse address %q: %q", in, err)
   173		}
   174		parts := strings.SplitN(addr.Address, "@", 2)
   175		if len(parts) != 2 {
   176			return "", trace.BadParameter("could not find local part in %q", addr.Address)
   177		}
   178		return parts[0], nil
   179	}
