   191	// Interpolate interpolates the variable adding prefix and suffix if present,
   192	// returns trace.NotFound in case if the trait is not found, nil in case of
   193	// success and BadParameter error otherwise
   194	func (p *Expression) Interpolate(traits map[string][]string) ([]string, error) {
   195		if p.namespace == LiteralNamespace {
   196			return []string{p.variable}, nil
   197		}
   198		values, ok := traits[p.variable]
   199		if !ok {
   200			return nil, trace.NotFound("variable is not found")
   201		}
   202		out := make([]string, len(values))
   203		for i := range values {
   204			val := values[i]
   205			var err error
   206			if p.transform != nil {
   207				val, err = p.transform.transform(val)
   208				if err != nil {
   209					return nil, trace.Wrap(err)
   210				}
